using Microsoft.EntityFrameworkCore;

public interface IRepository<T> where T : class
{
    IQueryable<T> Query();
    void Update(T entity); // calls DbSet<T>.Update
}

// "Application" code, yet every query needs EF Core's extension methods
public sealed class Checkout(IRepository<Order> orders, IUnitOfWork uow)
{
    public async Task RunAsync(int orderId, CancellationToken ct)
    {
        var order = await orders.Query()
            .Include(o => o.Lines)
            .SingleAsync(o => o.Id == orderId, ct);
        order.Submit();
        orders.Update(order); // marks every column as modified
        await uow.SaveChangesAsync(ct);
    }
}

namespace Shop.Application;

// The use case owns its ports and names them after what it needs
public interface IOrderRepository
{
    Task<Order> GetForCheckoutAsync(int orderId, CancellationToken ct);
}
public interface IUnitOfWork
{
    Task SaveChangesAsync(CancellationToken ct);
}

// No EF Core here: a unit test stubs GetForCheckoutAsync directly
public sealed class Checkout(IOrderRepository orders, IUnitOfWork uow)
{
    public async Task RunAsync(int orderId, CancellationToken ct)
    {
        var order = await orders.GetForCheckoutAsync(orderId, ct);
        order.Submit();
        await uow.SaveChangesAsync(ct); // writes only what changed
    }
}

