using Microsoft.EntityFrameworkCore;
using Shop.Application;

namespace Shop.Infrastructure;

public sealed class ShopDb(DbContextOptions<ShopDb> options)
    : DbContext(options), IUnitOfWork
{
    public DbSet<Order> Orders => Set<Order>();
    Task IUnitOfWork.SaveChangesAsync(CancellationToken ct) =>
        SaveChangesAsync(ct);
}

public sealed class EfOrderRepository(ShopDb db) : IOrderRepository
{
    public Task<Order> GetForCheckoutAsync(int orderId, CancellationToken ct) =>
        db.Orders.Include(o => o.Lines).SingleAsync(o => o.Id == orderId, ct);
}
